import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:chroniccare/core/data/repositories/vent_repository_impl.dart';import 'package:chroniccare/core/data/services/vent_audio_storage.dart';import 'package:chroniccare/domain/entities/vent_entry.dart';import 'package:chroniccare/domain/repositories/vent_repository.dart';import 'package:chroniccare/presentation/providers/core_providers.dart';/// v0.17 round 14 (P1-3 拆 core_providers): vent-specific provider////// 之前在 core_providers.dart 里。vent 是独立 privacy 模块,stream provider/// 跟 vent 业务紧绑,放 core_providers 不合适。////// 整组放这里 (含 vent repository, 跟 vent audio storage 同组), 避免/// core_providers ↔ vent_providers 循环 import。////// autoDispose: 离开 vent 列表页时 stream subscription 自动取消/// (隐私边界 + 省资源, round 8 C5 决策)/// 树洞 audio 文件管理（独立 service）final ventAudioStorageProvider = Provider<VentAudioStorage>(  (ref) => VentAudioStorage(),);/// v0.15 (Round 18) 树洞仓库 providerfinal ventRepositoryProvider = Provider<VentRepository>(  (ref) => VentRepositoryImpl(    ref.watch(databaseProvider),    ref.watch(ventAudioStorageProvider),  ),);/// 树洞条目流（按时间倒序，UI 监听用）////// v0.17 round 8 (C5): 加 .autoDispose，离开 vent 列表页时 stream subscription 自动/// 取消，DB watch 释放。重新进页面 re-subscribe 一次性重 fetch。树洞数据通常/// 几十~几百条，re-fetch 成本可接受；好处是切到 home/settings 后不再后台/// 监听 vent 表的更新（隐私边界 + 省资源）。final ventEntriesProvider = StreamProvider.autoDispose<List<VentEntryEntity>>(  (ref) => ref.watch(ventRepositoryProvider).watchAll(),);/// 单条树洞（详情页用）////// v0.17 round 8 (C5): 加 .autoDispose，详情页 pop 后缓存自动清。final ventEntryByIdProvider =    FutureProvider.autoDispose.family<VentEntryEntity?, int>(  (ref, id) => ref.watch(ventRepositoryProvider).getById(id),);